{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Autoradiography in guinea pigs showed that intravenously administered [3H]-LY686017, a high-MW lipophilic molecule with two CF3 groups and a heteroaromatic core, localized in brain, demonstrating that CF3-rich molecules can achieve meaningful CNS access despite large size.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "PD156707, a CF3-containing aniline with a carboxylic acid, crossed the BBB in dogs as shown by CSF levels, indicating that polar/acidic functionality does not automatically preclude CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "BPN14770, a lipophilic CF3-containing molecule with a carboxylic acid, achieved a brain-to-plasma ratio of 0.4–0.42 in mice, an adequate CNS distribution level.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Lapatinib, a structurally related anilinoquinazoline with a 3-chloro-4-ether aniline, showed very low brain/plasma ratios (<0.13) in rats, indicating poor CNS access.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "A methoxy analogue with high P-gp efflux had B/P=0.19 in rats, showing that efflux can severely limit brain penetration in related polar amide-containing compounds.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a pyrrolopyrimidine BTK inhibitor with a 3-hydroxy-3-methylbutanamide side chain, a motif associated with reduced P-gp efflux and CNS penetration. Although lapatinib and some polar analogues show poor brain exposure due to efflux, high-transfer evidence from CF3-rich CNS penetrants and adequate brain/plasma ratios in related molecules supports meaningful CNS access. The unfavorable physicochemical prior is overridden by the transferable experimental evidence and the known brain-penetrant behavior of this chemotype.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query molecule is included in the provided evidence.",
    "The query's exact P-gp/BCRP efflux ratio is not directly measured; the prior suggests moderate efflux risk.",
    "Human CNS penetration data for the query are not provided.",
    "The transferability of lapatinib's efflux-limited poor CNS access is uncertain because the query's hydroxyamide side chain may reduce transporter recognition."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

